document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',()=>{document.body.classList.remove('menu-open')})); 
const reels=[['حلاوة الكيمياء في بساطتها','شرح سريع يخليك تشوف المعلومة بشكل مختلف'],['افهمها مش تحفظها','فكرة كيمياء في دقيقة واحدة'],['سؤال اليوم مع الغزالي','اختبر فهمك قبل ما تكمل مذاكرة'],['نصيحة تفرق معاك','خطوة صغيرة تقرّبك من الدرجة النهائية']];const reelUrls=['https://www.facebook.com/reel/1900454814030820/','https://www.facebook.com/reel/1955985251532728/','https://www.facebook.com/reel/1088108914077452/','https://www.facebook.com/reel/1128655579635361/'];const reelsSection=document.createElement('section');reelsSection.id='reels';reelsSection.className='section reels';reelsSection.innerHTML='<div class="section-heading"><div><p class="eyebrow">من شرح المستر</p><h2>شوف الكيمياء<br><em>بطريقة مختلفة.</em></h2></div><p>أربع لقطات سريعة من محتوى الأستاذ إسلام الغزالي — افهم، طبّق، وكمّل.</p></div><div class="reels-grid">'+reels.map((item,i)=>'<article class="reel-card"><a href="'+reelUrls[i]+'" target="_blank" rel="noreferrer"><div class="reel-cover" style="background-image:linear-gradient(180deg,#071c2b00 35%,#071c2bcc),url(reel-'+(i+1)+'.jpg)"><span class="reel-play">▶</span><span class="reel-number">0'+(i+1)+'</span></div><div class="reel-info"><b>'+item[0]+'</b><small>'+item[1]+'</small><span>شاهد الريل ↗</span></div></a></article>').join('')+'</div>';document.querySelector('#social').before(reelsSection);document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="#reels">الريلز</a>');
const booking=document.createElement('section');booking.id='booking';booking.className='section booking';booking.innerHTML=`<div class="section-heading"><div><p class="eyebrow">احجز مكانك</p><h2>اختار يومك<br><em>وابدأ صح.</em></h2></div><p>املأ بياناتك، اختار اليوم والوقت المناسب، وهنوصلك بتفاصيل الحجز على WhatsApp.</p></div><div class="booking-layout"><form class="booking-form" id="booking-form"><label>اسم الطالب<input id="student-name" required placeholder="اكتب الاسم"></label><label>الصف الدراسي<input id="student-grade" required placeholder="مثال: ثالثة ثانوي"></label><label>الوقت المفضل<select id="student-time" required><option value="">اختر وقتًا</option><option>بعد الظهر</option><option>المساء</option><option>أي وقت مناسب</option></select></label><p class="chosen-date" id="chosen-date">اليوم المختار: لم يتم الاختيار</p><button class="button booking-submit" type="submit">إرسال طلب الحجز عبر WhatsApp ↗</button></form><div class="calendar-box"><div class="calendar-head"><button type="button" id="next-month">→</button><strong id="calendar-title"></strong><button type="button" id="prev-month">←</button></div><div class="weekdays"><span>سبت</span><span>أحد</span><span>إثن</span><span>ثلا</span><span>أربع</span><span>خمي</span><span>جمع</span></div><div class="calendar-grid" id="calendar-grid"></div></div></div>`;document.querySelector('#contact').before(booking);document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="#booking">الحجز</a>');let calendarDate=new Date(),selectedDate='';const titleEl=document.querySelector('#calendar-title'),gridEl=document.querySelector('#calendar-grid'),chosenEl=document.querySelector('#chosen-date');function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth();titleEl.textContent=new Intl.DateTimeFormat('ar-EG',{month:'long',year:'numeric'}).format(calendarDate);gridEl.innerHTML='';const first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=(first.getDay()+1)%7;for(let i=0;i<offset;i++)gridEl.insertAdjacentHTML('beforeend','<span class="empty-day"></span>');for(let d=1;d<=days;d++){const btn=document.createElement('button');btn.type='button';btn.textContent=d;btn.addEventListener('click',()=>{selectedDate=new Date(y,m,d).toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});chosenEl.textContent='اليوم المختار: '+selectedDate;gridEl.querySelectorAll('button').forEach(x=>x.classList.remove('selected-day'));btn.classList.add('selected-day')});gridEl.appendChild(btn)}}document.querySelector('#prev-month').addEventListener('click',()=>{calendarDate.setMonth(calendarDate.getMonth()-1);renderCalendar()});document.querySelector('#next-month').addEventListener('click',()=>{calendarDate.setMonth(calendarDate.getMonth()+1);renderCalendar()});document.querySelector('#booking-form').addEventListener('submit',e=>{e.preventDefault();if(!selectedDate){chosenEl.textContent='اختار يوم الحجز أولًا';return}const msg='طلب حجز جديد%0Aالاسم: '+encodeURIComponent(document.querySelector('#student-name').value)+'%0Aالصف: '+encodeURIComponent(document.querySelector('#student-grade').value)+'%0Aالوقت: '+encodeURIComponent(document.querySelector('#student-time').value)+'%0Aاليوم: '+encodeURIComponent(selectedDate);window.open('https://wa.me/201010591026?text='+msg,'_blank')});renderCalendar();
document.querySelector('.social-grid').insertAdjacentHTML('beforeend','<a href="https://www.facebook.com/GhazalyForEver/reels/" target="_blank" rel="noreferrer"><span class="social-icon">▶</span><b>Facebook Reels</b><small>شوف فيديوهات المستر</small><i>↗</i></a>');
